/// <summary>
///  The <c>METTransferOrderFinalisationBusinessEvent</c> class extends <c>BusinessEventsBase</c> to provide sales order extract business event.
/// </summary>
[BusinessEvents(classStr(METTransferOrderFinalisationBusinessEventContract),
    "@MET:TransferOrderFinalisationBusinessEventName",
    "@MET:TransferOrderFinalisationBusinessEventDesc",
    ModuleAxapta::Inventory)]
public final class METTransferOrderFinalisationBusinessEvent extends BusinessEventsBase
{
    private InventTransferTable inventTransferTable;

}

