/// <summary>
/// Constructs a new METTransferOrderFinalisationBusinessEvent business event.
/// </summary>
/// <param name = "_inventTransferTable">The <c>InventTransferTable</c> record.</param>
/// <returns>A new <c>METTransferOrderFinalisationBusinessEvent</c> business event.</returns>
public static METTransferOrderFinalisationBusinessEvent newFromInventTransferTable(InventTransferTable _inventTransferTable)
{
    METTransferOrderFinalisationBusinessEvent event = new METTransferOrderFinalisationBusinessEvent();
    event.parmInventTransferTable(_inventTransferTable);

    return event;
}

/// <summary>
/// Gets and sets <c>InventTransferTable</c>.
/// </summary>
/// <param name = "_inventTransferTable">
/// <c>InventTransferTable</c>.
/// </param>
/// <returns>
/// <c>InventTransferTable</c>.
/// </returns>
private InventTransferTable parmInventTransferTable(InventTransferTable _inventTransferTable = inventTransferTable)
{
    inventTransferTable = _inventTransferTable;
    return inventTransferTable;
}

/// <summary>
/// Constructs a new METTransferOrderFinalisationBusinessEventContract business event data contract.
/// </summary>
/// <returns>
/// A new <c>METTransferOrderFinalisationBusinessEventContract</c> business event data contract.
/// </returns>
[Wrappable(true), Replaceable(true)]
protected BusinessEventsContract buildContract()
{
    return METTransferOrderFinalisationBusinessEventContract::newFromInventTransferTable(inventTransferTable);
}
